item.text:
{
  "packet_id": "H6-T06-3",
  "claims": [
    {
      "claim_id": "C001",
      "fields": ["state"],
      "component": {
        "component_id": "C001.value",
        "value": "Unmet demand at each branch may change through the year.",
        "scope": "A possibility to accommodate in the trial, not an assertion that demand actually changes.",
        "provenance": {
          "refs": [{"source_id": "P001", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly attributes potential annual variation to unmet demand."
        }
      }
    },
    {
      "claim_id": "C002",
      "fields": ["state"],
      "component": {
        "component_id": "C002.value",
        "value": "Staff capacity at each branch may change through the year.",
        "scope": "A possibility to accommodate in the trial, not an assertion that capacity actually changes.",
        "provenance": {
          "refs": [{"source_id": "P001", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span separately includes staff capacity in the potentially changing state."
        }
      }
    },
    {
      "claim_id": "C003",
      "fields": ["state"],
      "component": {
        "component_id": "C003.value",
        "value": "Door counts, program attendance, surveys and workload reports measure different aspects of unmet demand and staff capacity.",
        "scope": "The mapping's four evidence streams; no specific one-to-one assignment of measures to aspects is supplied.",
        "provenance": {
          "refs": [
            {"source_id": "P002", "role": "SUPPORT"},
            {"source_id": "P001", "role": "CONTEXT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P002 supplies the measurement distinction; P001 resolves the state being measured."
        }
      }
    },
    {
      "claim_id": "C004",
      "fields": ["state"],
      "component": {
        "component_id": "C004.value",
        "value": "Disagreement among the four evidence streams does not establish which opening hours should be transferred.",
        "scope": "The insufficiency concerns disagreement itself, not a claim that the evidence streams cannot inform the decision.",
        "provenance": {
          "refs": [{"source_id": "P002", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span directly states this limit on what disagreement establishes."
        }
      }
    },
    {
      "claim_id": "C005",
      "fields": ["state"],
      "component": {
        "component_id": "C005.value",
        "value": "The proposed three-month trial assumes that shifts can be rearranged within the existing staffing budget, and that assumption requires verification before launch.",
        "scope": "An unverified feasibility assumption, not an established fact about staffing.",
        "provenance": {
          "refs": [{"source_id": "P003", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The assumption and its prelaunch verification qualification occur together."
        }
      }
    },
    {
      "claim_id": "C006",
      "fields": ["state"],
      "component": {
        "component_id": "C006.value",
        "value": "A short baseline may inadequately represent seasonal variation.",
        "scope": "A possible limitation of baseline coverage; the mapping does not establish that its preferred six-week baseline resolves this limitation.",
        "provenance": {
          "refs": [
            {"source_id": "P005", "role": "SUPPORT"},
            {"source_id": "P004", "role": "CONTEXT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P005 supplies the limitation; P004 identifies the proposed baseline."
        }
      }
    },
    {
      "claim_id": "C007",
      "fields": ["operation"],
      "component": {
        "component_id": "C007.value",
        "value": "The proposed fixed transfer of specified weekday hours to weekend hours at each branch is constrained to preserve funded staffing hours.",
        "scope": "A design constraint on the proposed transfer, not evidence that a feasible allocation has been found.",
        "provenance": {
          "refs": [{"source_id": "P006", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span specifies the transfer and its staffing-hours bound."
        }
      }
    },
    {
      "claim_id": "C008",
      "fields": ["operation"],
      "component": {
        "component_id": "C008.value",
        "value": "Raw totals should be examined alongside rates per open hour to avoid concealing reduced weekday service.",
        "scope": "The proposed joint examination of totals and rates; neither measure is declared sufficient by itself.",
        "provenance": {
          "refs": [{"source_id": "P011", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span supplies both the proposed comparison and its rationale."
        }
      }
    },
    {
      "claim_id": "C009",
      "fields": ["operation"],
      "component": {
        "component_id": "C009.value",
        "value": "The proposed benefit rule requires total weekly visits to exceed the baseline median by at least 10% in at least four of the final six weeks, with the sequence also assessed against baseline variation.",
        "scope": "A proposed trial rule. The percentage, reference statistic, persistence requirement and baseline-variation assessment form the stated criterion; this does not establish the threshold's meaningfulness.",
        "provenance": {
          "refs": [{"source_id": "P012", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The complete rule and its proposed status are contained in the cited span."
        }
      }
    },
    {
      "claim_id": "C010",
      "fields": ["operation"],
      "component": {
        "component_id": "C010.value",
        "value": "The proposed 10% threshold is not an established meaningful difference.",
        "scope": "The epistemic qualification applies to the proposed visit-increase threshold.",
        "provenance": {
          "refs": [{"source_id": "P012", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly distinguishes proposing the threshold from establishing its meaningfulness."
        }
      }
    },
    {
      "claim_id": "C011",
      "fields": ["signal"],
      "component": {
        "component_id": "C011.value",
        "value": "The proposed temporal signals are persistent gains or losses, trends, reversals and guardrail crossings across repeated observations.",
        "scope": "Patterns to look for during the trial, not a report that any have occurred.",
        "provenance": {
          "refs": [{"source_id": "P014", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span identifies the temporal pattern family and its repeated-observation basis."
        }
      }
    },
    {
      "claim_id": "C012",
      "fields": ["signal"],
      "component": {
        "component_id": "C012.value",
        "value": "Weekend use alone is insufficient for assessment; total use, weekday access, persistent unmet-demand reports and workload must also be examined.",
        "scope": "A limit on evaluating the trial from weekend use alone; no favorable or unfavorable outcomes are asserted.",
        "provenance": {
          "refs": [{"source_id": "P015", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The insufficiency and the dimensions qualifying that assessment are stated together."
        }
      }
    },
    {
      "claim_id": "C013",
      "fields": ["signal"],
      "component": {
        "component_id": "C013.value",
        "value": "Assessment should distinguish patterns recurring under comparable school-term and transport conditions from patterns coinciding with changes in those conditions.",
        "scope": "A proposed contextual comparison; coincidence is not asserted to establish causation.",
        "provenance": {
          "refs": [{"source_id": "P016", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly requests this distinction between contextual recurrence and coincidence with contextual change."
        }
      }
    },
    {
      "claim_id": "C014",
      "fields": ["signal"],
      "component": {
        "component_id": "C014.value",
        "value": "Conflicting sequences remain evidence and should not be collapsed into a single favorable score.",
        "scope": "Conflicting trial sequences; the mapping preserves their disagreement rather than specifying an aggregation rule.",
        "provenance": {
          "refs": [{"source_id": "P017", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The evidentiary status of disagreement and the associated restriction on aggregation are explicit."
        }
      }
    },
    {
      "claim_id": "C015",
      "fields": ["inference"],
      "component": {
        "component_id": "C015.value",
        "value": "At three months, meeting the predefined benefit rule is a necessary condition for proposing to keep a branch's schedule.",
        "scope": "One necessary condition in a conjunction; satisfying it alone does not authorize retention.",
        "provenance": {
          "refs": [
            {"source_id": "P018", "role": "SUPPORT"},
            {"source_id": "P012", "role": "CONTEXT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P018 supplies the necessary-condition relation; P012 identifies the referenced benefit rule."
        }
      }
    },
    {
      "claim_id": "C016",
      "fields": ["inference"],
      "component": {
        "component_id": "C016.value",
        "value": "At three months, gains distinguishable from plausible baseline fluctuation are a necessary condition for proposing to keep a branch's schedule.",
        "scope": "One necessary condition in the joint retention criterion, not an independently sufficient reason to retain the schedule.",
        "provenance": {
          "refs": [{"source_id": "P018", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The only-if construction explicitly makes this distinction a retention requirement."
        }
      }
    },
    {
      "claim_id": "C017",
      "fields": ["inference"],
      "component": {
        "component_id": "C017.value",
        "value": "At three months, holding within the access guardrails is a necessary condition for proposing to keep a branch's schedule.",
        "scope": "One necessary condition in the joint retention criterion; compliance alone is insufficient.",
        "provenance": {
          "refs": [
            {"source_id": "P018", "role": "SUPPORT"},
            {"source_id": "P007", "role": "CONTEXT"},
            {"source_id": "P013", "role": "CONTEXT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P018 supplies the retention condition; P007 and P013 identify the planned access guardrails and thresholds."
        }
      }
    },
    {
      "claim_id": "C018",
      "fields": ["inference"],
      "component": {
        "component_id": "C018.value",
        "value": "At three months, holding within the workload guardrails is a necessary condition for proposing to keep a branch's schedule.",
        "scope": "One necessary condition in the joint retention criterion; compliance alone is insufficient.",
        "provenance": {
          "refs": [
            {"source_id": "P018", "role": "SUPPORT"},
            {"source_id": "P007", "role": "CONTEXT"},
            {"source_id": "P013", "role": "CONTEXT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P018 supplies the retention condition; P007 and P013 identify the planned workload guardrails and thresholds."
        }
      }
    },
    {
      "claim_id": "C019",
      "fields": ["inference"],
      "component": {
        "component_id": "C019.value",
        "value": "At three months, staffing remaining within budget is a necessary condition for proposing to keep a branch's schedule.",
        "scope": "One necessary condition in the joint retention criterion; budget compliance alone is insufficient.",
        "provenance": {
          "refs": [{"source_id": "P018", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span expressly includes the staffing-budget condition in the only-if rule."
        }
      }
    },
    {
      "claim_id": "C020",
      "fields": ["inference"],
      "component": {
        "component_id": "C020.value",
        "value": "If repeated evidence identifies useful weekend demand alongside avoidable weekday losses, propose changing the allocation.",
        "scope": "A conditional recommendation to revise hours, not an assertion that useful demand or avoidable losses exist.",
        "provenance": {
          "refs": [{"source_id": "P019", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "This weekday-loss branch of the revision condition is supported under either plausible scope of the sentence's alternative."
        }
      }
    },
    {
      "claim_id": "C021",
      "fields": ["inference"],
      "component": {
        "component_id": "C021.value",
        "value": "Manageable workload problems identified by repeated evidence form an alternative trigger for proposing an allocation change, with ambiguity about whether useful weekend demand must accompany that trigger.",
        "scope": "The workload alternative in the revision rule. The annotation leaves unresolved whether useful weekend demand qualifies both alternatives or only the weekday-loss alternative.",
        "provenance": {
          "refs": [{"source_id": "P019", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span supplies the workload alternative; the annotation preserves rather than resolves its possible attachment ambiguity."
        }
      }
    },
    {
      "claim_id": "C022",
      "fields": ["inference"],
      "component": {
        "component_id": "C022.value",
        "value": "When the allocation is revised under the proposed change rule, measurement should be repeated after the change.",
        "scope": "Follow-up to a revision prompted by repeated evidence of the stated demand, access or workload pattern; it does not imply that the original trial establishes the revised schedule's outcome.",
        "provenance": {
          "refs": [{"source_id": "P019", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The sentence expressly links a proposed allocation change to renewed measurement."
        }
      }
    },
    {
      "claim_id": "C023",
      "fields": ["inference"],
      "component": {
        "component_id": "C023.value",
        "value": "If benefits fail the benefit rule, restore the original schedule.",
        "scope": "One stated sufficient trigger for restoration; it does not require harms also to outweigh gains.",
        "provenance": {
          "refs": [
            {"source_id": "P020", "role": "SUPPORT"},
            {"source_id": "P012", "role": "CONTEXT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P020 supplies this alternative restoration trigger; P012 identifies the referenced rule."
        }
      }
    },
    {
      "claim_id": "C024",
      "fields": ["inference"],
      "component": {
        "component_id": "C024.value",
        "value": "If persistent harms outweigh gains, restore the original schedule.",
        "scope": "An alternative restoration trigger; the mapping supplies no quantitative formula for weighing harms against gains.",
        "provenance": {
          "refs": [{"source_id": "P020", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The second alternative explicitly requires persistence and harms outweighing gains."
        }
      }
    },
    {
      "claim_id": "C025",
      "fields": ["inference"],
      "component": {
        "component_id": "C025.value",
        "value": "If safe staffing cannot be maintained, suspend the affected trial hours immediately.",
        "scope": "Immediate suspension of affected hours, not necessarily termination of every trial hour at both branches.",
        "provenance": {
          "refs": [{"source_id": "P021", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span provides the staffing-safety trigger, immediacy and affected-hours limitation."
        }
      }
    },
    {
      "claim_id": "C026",
      "fields": ["inference"],
      "component": {
        "component_id": "C026.value",
        "value": "If the budget cannot be maintained, suspend the affected trial hours immediately.",
        "scope": "An alternative immediate-suspension trigger; it does not require unsafe staffing also to occur.",
        "provenance": {
          "refs": [{"source_id": "P021", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The budget condition is an explicit alternative trigger for immediate suspension."
        }
      }
    },
    {
      "claim_id": "C027",
      "fields": ["inference"],
      "component": {
        "component_id": "C027.value",
        "value": "If evidence remains inconclusive, restore the original schedule pending a further trial that is explicitly authorized.",
        "scope": "An inconclusive outcome does not itself authorize continuation or a further trial.",
        "provenance": {
          "refs": [{"source_id": "P022", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span states restoration under inconclusiveness and retains the explicit-authorization qualification."
        }
      }
    },
    {
      "claim_id": "C028",
      "fields": ["inference"],
      "component": {
        "component_id": "C028.value",
        "value": "If evidence remains inconclusive, success should not be inferred.",
        "scope": "A bound on inference from inconclusive trial evidence, distinct from the operational restoration response.",
        "provenance": {
          "refs": [{"source_id": "P022", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly rejects inferring success in this condition."
        }
      }
    },
    {
      "claim_id": "C029",
      "fields": ["limit"],
      "component": {
        "component_id": "C029.value",
        "value": "The observed sequences can support an inference of sustained demand under the tested schedule.",
        "scope": "A possible inference restricted to the tested schedule; no actual sustained demand is asserted.",
        "provenance": {
          "refs": [
            {"source_id": "P023", "role": "SUPPORT"},
            {"source_id": "P010", "role": "CONTEXT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P023 supplies the qualified inferential capability; P010 identifies the reviewed sequences."
        }
      }
    },
    {
      "claim_id": "C030",
      "fields": ["limit"],
      "component": {
        "component_id": "C030.value",
        "value": "The observed sequences cannot by themselves establish that the tested schedule caused the changes.",
        "scope": "A limit on causal attribution from the sequences alone, not a claim that causal assessment is impossible with other evidence.",
        "provenance": {
          "refs": [
            {"source_id": "P023", "role": "SUPPORT"},
            {"source_id": "P010", "role": "CONTEXT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "The causal limitation and the by-themselves qualifier are explicit."
        }
      }
    },
    {
      "claim_id": "C031",
      "fields": ["limit"],
      "component": {
        "component_id": "C031.value",
        "value": "The observed sequences cannot by themselves predict year-round demand.",
        "scope": "A temporal generalization limit on the trial sequences alone.",
        "provenance": {
          "refs": [
            {"source_id": "P023", "role": "SUPPORT"},
            {"source_id": "P010", "role": "CONTEXT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P023 separately states the year-round prediction limit; P010 resolves the sequence reference."
        }
      }
    },
    {
      "claim_id": "C032",
      "fields": ["limit"],
      "component": {
        "component_id": "C032.value",
        "value": "Measurement error can create apparent trends.",
        "scope": "A possible source of apparent trends in the trial evidence, not an assertion that error occurred.",
        "provenance": {
          "refs": [{"source_id": "P024", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "Measurement error is explicitly included among possible creators of apparent trends."
        }
      }
    },
    {
      "claim_id": "C033",
      "fields": ["limit"],
      "component": {
        "component_id": "C033.value",
        "value": "Repeat visits can create apparent trends.",
        "scope": "A possibility affecting interpretation of trial evidence; repeat visits are not asserted to be erroneous records.",
        "provenance": {
          "refs": [{"source_id": "P024", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly assigns this possible effect to repeat visits."
        }
      }
    },
    {
      "claim_id": "C034",
      "fields": ["limit"],
      "component": {
        "component_id": "C034.value",
        "value": "Survey selection can create apparent trends.",
        "scope": "A possible influence on the observed evidence, not a finding that this survey has a particular selection problem.",
        "provenance": {
          "refs": [{"source_id": "P024", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "Survey selection is explicitly listed as a possible source of apparent trends."
        }
      }
    },
    {
      "claim_id": "C035",
      "fields": ["limit"],
      "component": {
        "component_id": "C035.value",
        "value": "Regression to the mean can create apparent trends.",
        "scope": "A possible explanation of observed trends, not an assertion that regression to the mean explains the trial results.",
        "provenance": {
          "refs": [{"source_id": "P024", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span directly includes regression to the mean in the list of possible influences."
        }
      }
    },
    {
      "claim_id": "C036",
      "fields": ["limit"],
      "component": {
        "component_id": "C036.value",
        "value": "Missing observations can create apparent trends.",
        "scope": "A possible effect of missingness; no particular missing-data mechanism is specified.",
        "provenance": {
          "refs": [{"source_id": "P024", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "Missing observations are explicitly attributed this possible effect."
        }
      }
    },
    {
      "claim_id": "C037",
      "fields": ["limit"],
      "component": {
        "component_id": "C037.value",
        "value": "Seasonal transport changes can create apparent trends.",
        "scope": "A possible contextual influence on the trial sequences, not an assertion that a transport change occurred.",
        "provenance": {
          "refs": [{"source_id": "P024", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span includes seasonal transport changes among possible sources of apparent trends."
        }
      }
    },
    {
      "claim_id": "C038",
      "fields": ["limit"],
      "component": {
        "component_id": "C038.value",
        "value": "Changes in school conditions through the seasons can create apparent trends.",
        "scope": "School-related contextual changes, including the school-term conditions tracked by the mapping; no actual effect is asserted.",
        "provenance": {
          "refs": [
            {"source_id": "P024", "role": "SUPPORT"},
            {"source_id": "P016", "role": "CONTEXT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P024 supplies the possible trend-producing influence; P016 resolves the school context."
        }
      }
    },
    {
      "claim_id": "C039",
      "fields": ["limit"],
      "component": {
        "component_id": "C039.value",
        "value": "Altered programming can create apparent trends.",
        "scope": "A possible influence of program changes, not a finding that programming changed or explains any result.",
        "provenance": {
          "refs": [{"source_id": "P024", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly identifies altered programming as a possible source of apparent trends."
        }
      }
    },
    {
      "claim_id": "C040",
      "fields": ["limit"],
      "component": {
        "component_id": "C040.value",
        "value": "Periods before and after schedule revisions should be analyzed separately.",
        "scope": "An analysis boundary when the tested schedule changes; the mapping does not claim this separation alone establishes causation.",
        "provenance": {
          "refs": [{"source_id": "P025", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly prescribes separate analysis across schedule revisions."
        }
      }
    },
    {
      "claim_id": "C041",
      "fields": ["limit"],
      "component": {
        "component_id": "C041.value",
        "value": "Program attendance and door counts should not be treated as independent users.",
        "scope": "A restriction on interpreting the two measures as independent user counts; the amount of overlap is not specified.",
        "provenance": {
          "refs": [{"source_id": "P026", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span directly supplies the restriction without quantifying overlap."
        }
      }
    },
    {
      "claim_id": "C042",
      "fields": ["limit"],
      "component": {
        "component_id": "C042.value",
        "value": "If observations are sparse, the resulting uncertainty should be reported.",
        "scope": "A conditional reporting requirement; the mapping does not specify a numerical sparsity threshold.",
        "provenance": {
          "refs": [{"source_id": "P027", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "Sparse observations are an explicit alternative trigger for reporting uncertainty."
        }
      }
    },
    {
      "claim_id": "C043",
      "fields": ["limit"],
      "component": {
        "component_id": "C043.value",
        "value": "If thresholds prove poorly calibrated, the resulting uncertainty should be reported.",
        "scope": "A conditional reporting requirement, not a finding that the proposed thresholds are poorly calibrated.",
        "provenance": {
          "refs": [{"source_id": "P027", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "Poor threshold calibration is an explicit alternative trigger for reporting uncertainty."
        }
      }
    },
    {
      "claim_id": "C044",
      "fields": ["limit"],
      "component": {
        "component_id": "C044.value",
        "value": "If conditions lack comparable coverage, the resulting uncertainty should be reported.",
        "scope": "A conditional reporting requirement; no actual coverage deficiency is asserted.",
        "provenance": {
          "refs": [{"source_id": "P027", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "Lack of comparable condition coverage is an explicit alternative trigger for reporting uncertainty."
        }
      }
    },
    {
      "claim_id": "C045",
      "fields": ["limit"],
      "component": {
        "component_id": "C045.value",
        "value": "If observations are sparse, identify the additional repeated observations needed.",
        "scope": "A conditional evidence-planning response; neither the required observations nor their sufficiency is specified.",
        "provenance": {
